        """Scan system services"""
        try:
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, 
                               r'System\CurrentControlSet\Services') as key:
                i = 0
                while True:
                    try:
                        service_name = winreg.EnumKey(key, i)

