                                severity=ThreatSeverity.HIGH,
                                path=f'HKCR\\{ext}\\shell\\open\\command',
                                description=f'File association for {ext}',
                                details={'handler': command}
                            )
                            self.findings.append(finding)
                    except:
                        pass
            except:
                pass

