                                        finding_type='Browser Hijacking',
                                        severity=ThreatSeverity.MEDIUM,
                                        path=f'{path}\\{name}',
                                        description='Suspicious browser setting',
                                        details={'value': value}
                                    )
                                    self.findings.append(finding)

                            i += 1
                        except OSError:
